    function cloneAndRekeyQuestions(questionsArray, newPrefix) {
      if (!questionsArray) return [];
      return questionsArray.map((q, idx) => ({
        ...q,
        id: `${newPrefix}_q${idx + 1}`
      }));
    }

    function cloneAndRekeyQuestions(questionsArray, newPrefix) {
      if (!questionsArray) return [];
      return questionsArray.map((q, idx) => ({
        ...q,
        id: `${newPrefix}_q${idx + 1}`
      }));
    }

