function buildUnit5DynamicExercise(sentences, unitId, lessonId, exId) {
  const qList = [];
  const shuffle = (arr) => [...arr].sort(() => 0.5 - Math.random());

  const ensurePunctuation = (str) => {
    if (!str) return "";
    const trimmed = str.trim();
    if (/[.?!]$/.test(trimmed)) return trimmed;
    return trimmed + ".";
  };

  // 1. Single Word Matching (Q1) - using first 4 sentences
  const matchSents1 = sentences.slice(0, 4);
  qList.push({
    id: `u${unitId}l${lessonId}_ex${exId}_match1`,
    type: "matching",
    prompt: "İfadeleri Türkçe karşılıklarıyla eşleştirin.",
    pairs: matchSents1.map(s => ({
      left: s.trWord || s.tr,
      right: s.word || s.en
    }))
  });

  // 2. Phrase Matching (Q2) - using sentences 4 to 8
  const matchSents2 = sentences.slice(4, 8);
  qList.push({
    id: `u${unitId}l${lessonId}_ex${exId}_match_phrase`,
    type: "matching",
    prompt: "İfadeleri Türkçe karşılıklarıyla eşleştirin.",
    pairs: matchSents2.map(s => ({
      left: s.tr,
      right: s.en
    }))
  });

  // 3. Multiple Choice (Q3): EN to TR - using sentence 8
  if (sentences.length > 8) {
    const sA = sentences[8];
    const wrongSents = sentences.filter(s => s.en !== sA.en);
    const shuffledWrongs = shuffle(wrongSents);
    while (shuffledWrongs.length < 3) {
      shuffledWrongs.push({ en: "test", tr: "test" });
    }
    const options = shuffle([
      sA.tr,
      shuffledWrongs[0].tr,
      shuffledWrongs[1].tr,
      shuffledWrongs[2].tr
    ]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_mc_0`,
      type: "multiple-choice",
      prompt: `"${sA.en}" ifadesinin Türkçe karşılığı hangisidir?`,
      options: options,
      correctIndex: options.indexOf(sA.tr),
      enSentence: sA.en,
      isEngToTr: true
    });
  }

  // 4. Multiple Choice (Q4): TR to EN - using sentence 9
  if (sentences.length > 9) {
    const sA = sentences[9];
    const wrongSents = sentences.filter(s => s.en !== sA.en);
    const shuffledWrongs = shuffle(wrongSents);
    while (shuffledWrongs.length < 3) {
      shuffledWrongs.push({ en: "test", tr: "test" });
    }
    const options = shuffle([
      sA.en,
      shuffledWrongs[0].en,
      shuffledWrongs[1].en,
      shuffledWrongs[2].en
    ]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_mc_1`,
      type: "multiple-choice",
      prompt: `"${sA.tr}" ifadesinin İngilizce karşılığı hangisidir?`,
      options: options,
      correctIndex: options.indexOf(sA.en),
      enSentence: sA.en,
      isEngToTr: false
    });
  }

  // 5. Fill-in-the-blank Dropdown (Q5) - using sentence 10
  if (sentences.length > 10) {
    const sC = sentences[10];
    const getParticipleOptions = (word) => {
      const knownParticipleAlternates = {
        "obtained": ["obtained", "obtaining", "obtain", "obtains"],
        "analyzed": ["analyzed", "analyzing", "analyze", "analyzes"],
        "restricted": ["restricted", "restricting", "restrict", "restricts"],
        "isolated": ["isolated", "isolating", "isolate", "isolates"],
        "affected": ["affected", "affecting", "affect", "affects"],
        "designed": ["designed", "designing", "design", "designs"],
        "unsealed": ["unsealed", "unsealing", "unseal", "unseals"],
        "unpredictable": ["unpredictable", "predictable", "predict", "predicting"],
        "complicated": ["complicated", "complicating", "complicate", "complicates"],
        "unexpected": ["unexpected", "expecting", "expect", "expects"],
        "unverified": ["unverified", "verifying", "verify", "verifies"],
        "developed": ["developed", "developing", "develop", "develops"],
        "inhabited": ["inhabited", "inhabiting", "inhabit", "inhabits"],
        "united": ["united", "uniting", "unite", "unites"],
        "composed": ["composed", "composing", "compose", "composes"],
        "simplified": ["simplified", "simplifying", "simplify", "simplifies"],
        "exposed": ["exposed", "exposing", "expose", "exposes"],
        "classified": ["classified", "classifying", "classify", "classifies"],
        "produced": ["produced", "producing", "produce", "produces"],
        "emitted": ["emitted", "emitting", "emit", "emits"],
        "sent": ["sent", "sending", "send", "sends"],
        "surrounded": ["surrounded", "surrounding", "surround", "surrounds"],
        "generated": ["generated", "generating", "generate", "generates"],
        "expected": ["expected", "expecting", "expect", "expects"],
        "outlined": ["outlined", "outlining", "outline", "outlines"],
        "made": ["made", "making", "make", "makes"],
        "uninhabited": ["uninhabited", "inhabited", "inhabit", "inhabiting"],
        "reduced": ["reduced", "reducing", "reduce", "reduces"],
        "increased": ["increased", "increasing", "increase", "increases"]
      };
      if (knownParticipleAlternates[word.toLowerCase()]) {
        const list = knownParticipleAlternates[word.toLowerCase()];
        if (word[0] === word[0].toUpperCase()) {
          return list.map(w => w.charAt(0).toUpperCase() + w.slice(1));
        }
        return list;
      }
      return [word, word + "ed", word + "ing", word + "s"];
    };

    const blankPattern = new RegExp("\\b" + sC.word + "\\b", "g");
    const sentenceWithBlank = sC.en.replace(blankPattern, "___");
    const optionsRaw = getParticipleOptions(sC.word);
    const options = shuffle([...new Set(optionsRaw)]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_dropdown`,
      type: "fill-blank-dropdown",
      prompt: `Cümleyi tamamlayın: "${ensurePunctuation(sC.tr)}"`,
      sentence: sentenceWithBlank,
      options: options,
      correctIndex: options.indexOf(sC.word),
      enSentence: sC.en
    });
  }

  // 6. True-False Time-Attack Reflex Blitz (Q6) - using sentence 11
  if (sentences.length > 11) {
    const sD = sentences[11];
    const isCorrect = Math.random() > 0.5;
    let displayTr = sD.tr;
    if (!isCorrect) {
      const otherSents = sentences.filter(s => s.tr !== sD.tr);
      const randomOther = otherSents[Math.floor(Math.random() * otherSents.length)];
      displayTr = randomOther ? randomOther.tr : "insansız bölgeler";
    }
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_tf`,
      type: "true-false",
      prompt: "Mekanik: Doğruysa sağa kaydır (veya SAĞ tuş), yanlışsa sola kaydır (veya SOL tuş)!",
      englishPhrase: sD.en,
      turkishTranslation: displayTr,
      correctAnswer: isCorrect ? "true" : "false",
      explanation: `"${sD.en}" ifadesinin doğru Türkçe karşılığı "${sD.tr}" şeklindedir.`
    });
  }

  // 7. Word Bank English to Turkish (Q7) - using sentence 12
  if (sentences.length > 12) {
    const sE = sentences[12];
    const targetWords = sE.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_\`~()]/g, ""));
    const allOtherTrWords = sentences.filter(s => s.en !== sE.en).map(s => s.tr.split(/\s+/).map(w => w.replace(/[.,\/#!$%\^&\*;:{}=\-_\`~()]/g, ""))).flat();
    const uniqueDistractors = [...new Set(allOtherTrWords)].filter(w => !targetWords.includes(w));
    const shuffledDistractors = shuffle(uniqueDistractors);
    while (shuffledDistractors.length < 3) {
      shuffledDistractors.push("ve");
    }
    const words = shuffle([...targetWords, shuffledDistractors[0], shuffledDistractors[1], shuffledDistractors[2]]);
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_wb_tr`,
      type: "word-bank",
      prompt: "Cümlenin Türkçe karşılığını oluşturun:",
      translation: ensurePunctuation(sE.en),
      words: words,
      correctOrder: targetWords,
      enSentence: sE.en,
      isEngToTr: true
    });
  }

  // 8. Translation Text (Q8) - using sentence 13
  if (sentences.length > 13) {
    const sF = sentences[13];
    qList.push({
      id: `u${unitId}l${lessonId}_ex${exId}_tx`,
      type: "translation-text",
      prompt: `"${sF.en}" ifadesini Türkçe'ye çevirin:`,
      correctSentence: sF.tr,
      enSentence: sF.en,
      isEngToTr: true
    });
  }

  return qList;
}

